module Bi_Dir_Shift_Reg (output [1: 4] D_out, input [1: 4] D_in, input SEL, STB, SH_LD, clock, CLR_bar);  wire 			QD_bar;  wire [1: 4] 	Y;  SReg_74195 M0 (D_out[1], D_out[2], D_out[3], D_out[4], QD_bar, Y[1], Y[2], Y[3], Y[4],     SH_LD, D_out[4], D_out[4], CLR_bar, clock  );    Mux_74157 M1 (Y[1], Y[2], Y[3], Y[4], D_in[1], D_in[2], D_in[3], D_in[4], 						     D_out[2], D_out[3], D_out[4], D_out[1], SEL, STB		   );endmodulemodule SReg_74195 (  output reg 	QA, QB, QC, QD,   output 		QD_bar,   input 		A, B, C, D, SH_LD, J, K_bar, CLR_bar, CK);  assign 		QD_bar = ~QD;  always @ (posedge CK, negedge CLR_bar)    if (!CLR_bar) {QA, QB, QC, QD} <= 4'b0;    else if (!SH_LD) {QA, QB, QC, QD} <= {A, B, C, D};    else case ({J, K_bar})      2'b00: 	{QA, QB, QC, QD} <= {1'b0, QA, QB, QC};      2'b11: 	{QA, QB, QC, QD} <= {1'b1, QA, QB, QC};	      2'b01:	{QA, QB, QC, QD} <= {QA, QA, QB, QC};	// unused      2'b10:	{QA, QB, QC, QD} <= {~QA, QA, QB, QC};	// unused    endcaseendmodulemodule Mux_74157 (  output reg Y1, Y2, Y3, Y4,   input A1, A2, A3, A4, B1, B2, B3, B4, SEL, STB);  wire [4: 1] In_A = {A1, A2, A3, A4};  wire [4: 1] In_B = {B1, B2, B3, B4};  always @ (In_A, In_B, SEL, STB)    if (STB) {Y1, Y2, Y3, Y4} = 4'b0;    else if (SEL) {Y1, Y2, Y3, Y4} = In_B;	 // SEL = 1    else {Y1, Y2, Y3, Y4} = In_A;	 			// SEL = 0endmodulemodule t_Bi_Dir_Shift_Reg ();  wire [1: 4] D_out;  reg [1: 4] D_in;  reg SEL, STB, SH_LD, clock, CLR_bar;  Bi_Dir_Shift_Reg M0 (D_out, D_in, SEL, STB, SH_LD, clock, CLR_bar);  initial #200 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork    D_in = 4'h8;		// Data for walking 1 to right    CLR_bar = 0;    STB = 0;    SEL = 0;			// Selects D_in    SH_LD = 0;			// load D_in    #10 CLR_bar = 1;     #20 STB = 1;    #40 STB = 0;    #30 SH_LD = 1;	     #50 SH_LD = 0;	// Interrupt count to load    #60 SH_LD = 1;    #80 SEL = 1;    #100 STB = 1;    #130 STB = 0;    #140 SH_LD = 0;    //#150 SH_LD = 1;  joinendmodule